using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace Wildfolk.Editor
{
    public static class TierThreeQa
    {
        public static string Phase {get;private set;}="idle";
        private static WorldSaveService s;private static PlayerInventory bag;
        private static string Root=>Path.GetFullPath("Captures/tier-three");
        public static void Begin(){ContentExpansionQa.Prepare();s=ContentExpansionQa.S;bag=s.Player;if(s.World.Map.GenerationVersion!=3)throw new InvalidOperationException("Fresh isolated generation-three world required");Directory.CreateDirectory(Root);File.WriteAllText(Root+"/play.tsv","utc\tstep\tresult\n");s.StartCoroutine(Guard(Flow()));}
        private static IEnumerator Guard(IEnumerator flow)
        {var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object value;try{more=stack.Peek().MoveNext();value=more ? stack.Peek().Current : null;}catch(Exception e){Phase="failed";Log(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(value is IEnumerator child)stack.Push(child);else yield return value;}Phase="complete";Log("SP flows complete; local Host is separate");}
        private static void Log(string value)=>File.AppendAllText(Root+"/play.tsv",DateTime.UtcNow.ToString("O")+"\t"+Phase+"\t"+value.Replace('\n',' ')+"\n");
        private static void Check(bool value,string message){Log((value ? "PASS " : "FAIL ")+message);if(!value)throw new InvalidOperationException(message);}
        private static void Step(string name){Phase=name;Log("begin");}
        private static IEnumerator Capture(string name){ScreenCapture.CaptureScreenshot(Root+"/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        private static void Move(Vector2 p)=>ContentExpansionQa.Move(p);
        private static void Give(string id,int count=1)=>bag.Model.Add(s.Catalog.Item(id),count);
        private static void Select(string id)=>ContentExpansionQa.Select(id);
        private static WorldPlaceable Place(string id,Vector2 p)=>ContentExpansionQa.Place(id,p);
        private static void ClearBag(){bag.Model.Restore(new InventoryModel(bag.Model.Capacity).Capture(),s.Catalog);bag.SelectSlot(0);}
        private static int Slot(string id)=>Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==s.Catalog.Item(id));
        private static IEnumerator Craft(string id)
        {var recipe=s.Catalog.Recipe(id);foreach(var cost in recipe.Ingredients)bag.Model.Add(cost.Item,cost.Count);yield return null;var panel=UnityEngine.Object.FindFirstObjectByType<CraftingPanel>();var card=panel.Cards.Single(c=>c.Recipe.Id==id);bag.GetComponent<PlayerCrafting>().SetSelected(recipe);card.CraftButton.onClick.Invoke();Check(bag.Model.CountItem(recipe.Result)>0,"UI crafted "+id);yield return null;}
        private static IEnumerator Gather(string id)
        {
            Step("natural-"+id);var index=Array.FindIndex(s.World.Definition.Resources,r=>r.Prefab.Definition.DropItem.Id==id);var source=s.World.Map.Resources.First(p=>p.Rule==index);Move(source.Position+Vector2.down*1.5f);yield return null;
            var node=UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None).Single(r=>r.Id==source.Id).Node;var body=bag.GetComponent<PlayerAvatar>();body.Facing.Face((Vector2)node.transform.position-(Vector2)bag.transform.position);foreach(var other in UnityEngine.Object.FindObjectsByType<ResourceNode>(FindObjectsSortMode.None))if(other!=node && Vector2.Distance(other.transform.position,bag.transform.position)<3)other.gameObject.SetActive(false);Physics2D.SyncTransforms();
            Select("iron_pickaxe");var hp=node.Health.Current;bag.GetComponent<PlayerCombat>().TryAttack();yield return new WaitForSeconds(.7f);Check(node.Health.Current==hp,"Iron Pickaxe rejected");Select("steel_pickaxe");
            while(node!=null && node.Health.IsAlive){bag.GetComponent<PlayerCombat>().TryAttack();yield return new WaitForSeconds(.6f);}Check(node==null || !node.Health.IsAlive,"Steel Pickaxe harvested authored deep source; yield="+s.World.Definition.Resources[index].Prefab.Definition.DropCount);yield return Capture("deep-"+id);
            var region=s.World.Renewal.Population.Region(index,source.Position);foreach(var other in UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None))if(other.Rule==index && s.World.Renewal.Population.Region(index,other.transform.position)==region && s.World.Renewal.Population.Count(index,region)>=s.World.Renewal.Population.Target(index,region))other.Node.Health.ApplyDamage(other.Node.Health.Maximum);
            var serial=s.World.Renewal.Population.Serial;var rooms=s.World.Map.Continental.CaveAt(source.Position).Rooms;var retreat=rooms.Where(r=>Vector2.Distance(r.Center,source.Position)>30 && Vector2.Distance(r.Center,source.Position)<100).OrderBy(r=>Vector2.Distance(r.Center,source.Position)).First();Move(retreat.Center);yield return new WaitForSeconds(.2f);s.Clock.Model.Advance(301);for(var attempt=0;attempt<20 && s.World.Renewal.Population.Serial==serial;attempt++)s.World.Renewal.Tick();Check(s.World.Renewal.Population.Serial>serial,"regional replacement after fixture deficit and time advance; prior source ID remains destroyed");
        }
        private static IEnumerator Flow()
        {
            Step("workbench-III");Move(Vector2.zero);ContentExpansionQa.Clear(Vector2.zero,14);ClearBag();var bench=Place("workbench_ii",new Vector2(2,0)).GetComponent<CraftingStation>();var crafting=bag.GetComponent<PlayerCrafting>();crafting.OpenStation(bench);yield return null;var panel=UnityEngine.Object.FindFirstObjectByType<CraftingPanel>();Check(!crafting.UpgradeWorkbench(),"missing materials rejected");yield return Capture("01-III-requirements");foreach(var cost in bench.Definition.UpgradeCosts)bag.Model.Add(cost.Item,cost.Count);yield return null;panel.UpgradeButton.onClick.Invoke();yield return null;var third=WorldPlaceable.Active.Single(p=>p.Definition.Station==StationKind.Workbench && p.Definition.WorkbenchTier==3);crafting.OpenStation(third.GetComponent<CraftingStation>());yield return null;Check(crafting.AvailableStation==StationKind.Workbench,"III upgraded through UI callback");
            foreach(var id in new[]{"diamond_pickaxe","diamond_axe","diamond_sword","diamond_spear","diamond_head","diamond_body"}){yield return Craft(id);var old=id.Replace("diamond_","steel_");Check(bag.Model.CountItem(s.Catalog.Item(old))==0,"consumed "+old);}yield return Craft("mechanical_part");Check(bag.Model.CountItem(s.Catalog.Item("mechanical_part"))==2,"Mechanical Part output2");yield return Craft("telescope");yield return Craft("crystal_lantern");yield return Craft("signal_beacon");yield return Craft("turret_workbench");yield return Capture("02-III-crafting");crafting.CloseCrafting();Select("diamond_body");bag.GetComponent<PlayerPrimaryAction>().TryUse();Select("diamond_head");bag.GetComponent<PlayerPrimaryAction>().TryUse();Select("crystal_lantern");Check(bag.GetComponent<PlayerPrimaryAction>().TryUse(),"Crystal Lantern Utility equipped");Select("diamond_sword");Check(bag.GetComponent<PlayerEquipment>().Utility.Id=="crystal_lantern","Lantern remains while holding sword");
            yield return Gather("crystal");yield return Gather("diamond");
            Step("telescope");Move(Vector2.zero);Select("telescope");var input=bag.GetComponent<PlayerInputCommands>();Check(input.Attack(),"scope entered");var active=s.World.Chunks.WantedCount;input.SetMove(Vector2.right);yield return new WaitForSeconds(.8f);Check(input.Move==Vector2.zero && !input.Interact() && !input.Dash(),"scope blocks movement/interaction/dash");Check(active==s.World.Chunks.WantedCount && s.World.Chunks.PresentationOnlyCount>0,"distant presentation without simulation expansion");yield return Capture("03-telescope");bag.GetComponent<Health>().ApplyDamage(1);Check(!bag.GetComponent<PlayerTelescope>().IsViewing,"damage interrupts scope");yield return new WaitForSecondsRealtime(3.2f);Check(s.World.Chunks.PresentationOnlyCount==0,"presentation hysteresis expires");
            Step("beacons");Give("compass");var a=Place("signal_beacon",new Vector2(-3,1));var b=Place("signal_beacon",new Vector2(-5,2));var nav=bag.GetComponent<PlayerNavigation>();Check(nav.Mode!=NavigationMode.Beacon,"beacon tracking initially off");nav.SelectNavigation(NavigationMode.Beacon,b.SaveId);Check(nav.TryBeacon(out var destination,out _) && destination==(Vector2)b.transform.position,"single selected beacon bearing");yield return Capture("04-beacon-navigation");nav.SelectNavigation(NavigationMode.Off);Check(nav.Mode==NavigationMode.Off,"navigation hidden");nav.SelectNavigation(NavigationMode.Beacon,b.SaveId);
            Step("turret-workbench");ClearBag();Move(Vector2.zero);ContentExpansionQa.Clear(new Vector2(3,0),5);var workshop=Place("turret_workbench",new Vector2(3,0)).GetComponent<CraftingStation>();Move(new Vector2(1.5f,-1));Check(crafting.OpenStation(workshop),"turret workstation in interaction range");yield return null;foreach(var id in new[]{"ballista","repeater","ballista_bolt","auto_loader","auto_aim","ammo_box","rotation_gear","reinforced_frame"})yield return Craft(id);yield return Capture("05-turret-workbench");crafting.CloseCrafting();
            Step("manual-ballista");ContentExpansionQa.Clear(new Vector2(0,7),14);var t=Place("ballista",new Vector2(2,0)).GetComponent<WorldTurret>();var enemy=Target(new Vector2(2,9));Give("ballista_bolt",12);Check(TierThreeHud.OpenTurret(t,bag),"turret interaction modal");Check(t.Execute(bag,TurretOperation.Deposit,Slot("ballista_bolt")),"compatible ammunition inserted");Check(t.Execute(bag,TurretOperation.Reload),"manual load");Check(t.Execute(bag,TurretOperation.Aim,0,0),"manual aim");yield return new WaitForSeconds(.2f);Check(t.Execute(bag,TurretOperation.Fire),"manual projectile fire");Check(!t.Execute(bag,TurretOperation.Fire),"cooldown rejects duplicate shot");yield return new WaitForSeconds(.7f);Check(enemy.Current==938,"Ballista impact62");foreach(var id in new[]{"ammo_box","rotation_gear","reinforced_frame","auto_loader","auto_aim"}){Give(id);Check(t.Execute(bag,TurretOperation.Install,Slot(id)),"installed "+id);}yield return Capture("06-ballista-modules");Check(t.AmmoSlots==3 && t.GetComponent<Health>().Maximum==270,"ammo slots3 / frame maximum270");yield return new WaitForSeconds(3);Check(t.Shots>=2,"combined modules automatically fire real projectile");UnityEngine.Object.FindFirstObjectByType<TierThreeHud>().Close();UnityEngine.Object.Destroy(enemy.gameObject);
            Step("repeater");Move(new Vector2(-2,0));var repeater=Place("repeater",new Vector2(-2,2)).GetComponent<WorldTurret>();Give("crossbow_bolt",3);repeater.Execute(bag,TurretOperation.Deposit,Slot("crossbow_bolt"));Give("auto_loader");repeater.Execute(bag,TurretOperation.Install,Slot("auto_loader"));Give("auto_aim");repeater.Execute(bag,TurretOperation.Install,Slot("auto_aim"));var target=Target(new Vector2(-2,10));yield return new WaitForSeconds(3);Check(repeater.Shots==3 && repeater.AmmoCount()==0 && target.Current==952,"Repeater role16 damage / .55 recovery / finite ammo");UnityEngine.Object.Destroy(target.gameObject);yield return Capture("07-repeater-empty");
            Step("chunk-sleep-save");var idTurret=t.GetComponent<WorldPlaceable>().SaveId;var count=t.AmmoCount();Move(new Vector2(1100,1000));yield return null;var state=s.World.Chunks.DormantPlaces().Single(p=>p.Id==idTurret);Check(state.Turret.Ammo.Sum(x=>x.Count)==count,"distant turret cargo sleeps");Move(Vector2.zero);yield return null;t=WorldPlaceable.Active.Single(p=>p.SaveId==idTurret).GetComponent<WorldTurret>();Check(t.Modules[0]!=null && t.Modules[1]!=null && t.AmmoCount()==count,"return restores modules and ammunition");Check(s.Save(),"isolated save10 includes beacons/turrets/cargo/modules");yield return Capture("08-base");
        }
        private static Health Target(Vector2 p){var go=new GameObject("Isolated target");go.SetActive(false);var h=go.AddComponent<Health>();h.Definition=ScriptableObject.CreateInstance<VitalityDefinition>();h.Definition.MaximumHealth=1000;go.AddComponent<CircleCollider2D>().isTrigger=true;go.AddComponent<CombatAffiliation>().Relation=EntityRelation.Hostile;var view=go.AddComponent<SpriteRenderer>();view.sprite=UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Wildfolk/Art/skeleton.png");view.sharedMaterial=s.World.SpriteMaterial;view.sortingOrder=WorldSorting.Overlay;go.transform.position=p;go.SetActive(true);return h;}
    }
}
